INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist JSON immer hierarchisch aufgebaut?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch flach sein"}, {"text": "Ja", "correct": false, "because": "Flexibel strukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit JSON?', 3, '[{"text": "Daten strukturiert austauschen", "correct": true, "because": "Lesbar und leicht"}, {"text": "Datenbankstruktur definieren", "correct": false, "because": "Anderer Zweck"}, {"text": "UI gestalten", "correct": false, "because": "Kein direkter Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu JSON?', 5, '[{"text": "Key-Value-Paare", "correct": true, "because": "Grundstruktur"}, {"text": "Arrays", "correct": true, "because": "Listen von Werten"}, {"text": "Binärcodes", "correct": false, "because": "Textbasiert"}, {"text": "Stylesheets", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) JSON ist textbasiert. b) Parsing ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Parsing nötig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Arbeiten mit JSON?', 4, '[{"text": "Syntax", "correct": false, "because": "Muss korrekt sein"}, {"text": "Datenstruktur", "correct": false, "because": "Definiert Inhalt"}, {"text": "Farbcodierung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob JSON nur für APIs genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal einsetzbar"}, {"text": "Ja", "correct": false, "because": "Vielseitig nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich zum Parsen von JSON?', 3, '[{"text": "Bibliothek wie JSON.parse", "correct": true, "because": "Konvertiert zu Objekten"}, {"text": "Texteditor", "correct": false, "because": "Nur Anzeige"}, {"text": "Compiler", "correct": false, "because": "Für Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet JSON?', 5, '[{"text": "Lesbarkeit", "correct": true, "because": "Klar und einfach"}, {"text": "Kompatibilität", "correct": true, "because": "Weit verbreitet"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) JSON unterstützt verschachtelte Daten. b) Es ist binärbasiert. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Textbasiert"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für JSON?', 4, '[{"text": "Schlüssel", "correct": false, "because": "Definiert Struktur"}, {"text": "Werte", "correct": false, "because": "Inhalt des JSON"}, {"text": "3D-Modellierung", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist JSON nur für kleine Datenmengen?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierbar"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datentypen unterstützt JSON?', 4, '[{"text": "Strings", "correct": true, "because": "Textwerte"}, {"text": "Numbers", "correct": true, "because": "Numerische Werte"}, {"text": "Funktionen", "correct": false, "because": "Keine Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass JSON schwer zu parsen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Einfach mit Bibliotheken"}, {"text": "Ja", "correct": false, "because": "Leichtgewichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Parsen von JSON?', 3, '[{"text": "Fehlerbehandlung", "correct": true, "because": "Sichert Robustheit"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Korrektheit zählt"}, {"text": "Designanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) JSON ist maschinenlesbar. b) Es benötigt XML.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Unabhängig von XML"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es beim Parsen?', 5, '[{"text": "Syntaxfehler", "correct": true, "because": "Ungültiges JSON"}, {"text": "Datenverlust", "correct": true, "because": "Fehlerhafte Interpretation"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei JSON unwichtig?', 3, '[{"text": "Schlüsselnamen", "correct": false, "because": "Strukturieren Daten"}, {"text": "Werttypen", "correct": false, "because": "Definieren Inhalt"}, {"text": "Serverleistung", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt JSON Kommentare?', 3, '[{"text": "Nein", "correct": true, "because": "Kein offizieller Support"}, {"text": "Ja", "correct": false, "because": "Nur inoffiziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob JSON leicht zu erweitern ist?', 2, '[{"text": "Ja", "correct": true, "because": "Flexible Struktur"}, {"text": "Nein", "correct": false, "because": "Einfach anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich zum Parsen in JavaScript?', 4, '[{"text": "JSON.parse", "correct": true, "because": "Konvertiert String zu Objekt"}, {"text": "JSON.compile", "correct": false, "because": "Gibt es nicht"}, {"text": "JSON.read", "correct": false, "because": "Falsche Methode"}]');
